package server.life;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Ticket 81 (owner 2026-10-28, draft): max HP and EXP overrides by mob id. The table is a jar resource,
 * {@code soloMapling/mob-stat-overrides.tsv}, generated by tools/economy/gen_bb_drops.py (rules in
 * docs/economy/bb-drops/RULES.md):
 * <ul>
 *   <li>the post-Big-Bang mobs (Arcane River, Grandis, Future/Twilight Perion) and the Lion King's Castle / Rose
 *       Garden mobs get a classic-like HP for their level and EXP for about twice a classic spot's EXP per hour;</li>
 *   <li>the classic lv 95+ mobs of Leafre/Minar, Temple of Time and Ulu City get EXP x1.4.</li>
 * </ul>
 * LifeFactory applies a row after its own values, so a row wins over the WZ value and LifeFactory's hard-coded HP.
 * Nothing else changes. The client needs nothing for play: a normal mob's HP bar is the percentage the server sends,
 * a boss bar is the server's HP, and EXP is the server's.
 *
 * <p>Columns: mob id, max HP or {@code -}, EXP or {@code -}, comment. Off with {@code -Dslums.mobStatOverrides=false}
 * (read once, at the first mob load).
 */
public final class MobStatOverrides {

    private static final Logger log = LoggerFactory.getLogger(MobStatOverrides.class);
    static final String RESOURCE = "/soloMapling/mob-stat-overrides.tsv";

    /** One row; a null field keeps the mob's own value. */
    record Row(Long hp, Integer exp) {
    }

    private static final Map<Integer, Row> ROWS = load();

    private MobStatOverrides() {
    }

    /** The overriding max HP for {@code mobId}, or {@code fallback}. */
    public static long maxHp(int mobId, long fallback) {
        Row r = ROWS.get(mobId);
        return r != null && r.hp() != null ? r.hp() : fallback;
    }

    /** The overriding EXP for {@code mobId}, or {@code fallback}. */
    public static int exp(int mobId, int fallback) {
        Row r = ROWS.get(mobId);
        return r != null && r.exp() != null ? r.exp() : fallback;
    }

    static Map<Integer, Row> table() {
        return ROWS;
    }

    private static Map<Integer, Row> load() {
        if (!Boolean.parseBoolean(System.getProperty("slums.mobStatOverrides", "true"))) {
            log.info("mob stat overrides are off (-Dslums.mobStatOverrides=false)");
            return Collections.emptyMap();
        }
        try (InputStream in = MobStatOverrides.class.getResourceAsStream(RESOURCE)) {
            if (in == null) {
                log.warn("{} is missing from the jar; no mob stat overrides", RESOURCE);
                return Collections.emptyMap();
            }
            return parse(new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)));
        } catch (IOException | RuntimeException e) {
            log.error("cannot read {}; no mob stat overrides", RESOURCE, e);
            return Collections.emptyMap();
        }
    }

    static Map<Integer, Row> parse(BufferedReader r) throws IOException {
        Map<Integer, Row> out = new HashMap<>();
        String line;
        while ((line = r.readLine()) != null) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            String[] f = line.split("\t", -1);
            Long hp = "-".equals(f[1].trim()) ? null : Long.parseLong(f[1].trim());
            Integer exp = "-".equals(f[2].trim()) ? null : Integer.parseInt(f[2].trim());
            if ((hp != null && hp <= 0) || (exp != null && exp <= 0) || (hp == null && exp == null)) {
                throw new IllegalArgumentException("bad row (HP and EXP must be positive, one of them set): " + line);
            }
            if (out.put(Integer.parseInt(f[0].trim()), new Row(hp, exp)) != null) {
                throw new IllegalArgumentException("mob listed twice: " + line);
            }
        }
        return Collections.unmodifiableMap(out);
    }
}
